{
  "schema": "threatline.threatmodel.v1",
  "issueKey": "EVAL-07",
  "sketch": {
    "components": ["API gateway", "Request/response body logger", "Login endpoint", "Payment endpoint", "Central log system"],
    "dataStores": ["Central log system (1 year retention)"],
    "externalServices": [],
    "trustBoundaries": ["Internet to API gateway", "API gateway to central log system", "Log system to operators and support staff"],
    "dataClasses": ["payment", "credentials", "pii"],
    "exposure": "internal",
    "llmFeatures": false
  },
  "threats": [
    {
      "stride": "InformationDisclosure",
      "title": "Plaintext passwords from login requests end up in the central log system",
      "scenario": "The gateway writes whole login request bodies to logs, so every password submitted is stored in cleartext. Any employee, contractor or support tool with log read access, or an attacker who gets a single log-system credential or exported log bundle, harvests working passwords for many users and reuses them on this and other services. No exploitation of the application itself is needed.",
      "component": "API gateway body logger / central log system",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        { "quote": "the API gateway logs full request and response bodies, including login requests and payment details, to the central log system for 1 year" }
      ],
      "asvs": ["V16.3.3"],
      "cwe": ["CWE-532", "CWE-522"],
      "plainLanguage": "Users' passwords are written into the logs in plain text, so anyone who can read logs can log in as them.",
      "requirement": {
        "title": "Never log credentials",
        "given": "a request to an authentication endpoint",
        "when": "the API gateway writes the request to the log system",
        "then": "password, secret and token fields are redacted before the log record leaves the gateway, and logging of authentication request bodies is disabled by default"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Cardholder data is stored in logs for a year",
      "scenario": "Payment request and response bodies contain card numbers, expiry and verification codes. Logging them copies payment data into a store that is not built or scoped as a cardholder data environment. An insider or anyone who breaches the log system exfiltrates a year of card data in bulk, enabling fraud and a reportable payment-data incident.",
      "component": "Payment endpoint logging to central log system",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        { "quote": "including login requests and payment details, to the central log system for 1 year" }
      ],
      "asvs": ["V16.3.3"],
      "cwe": ["CWE-532", "CWE-312"],
      "plainLanguage": "Card details get copied into the logs, turning the log system into an unprotected copy of payment data.",
      "requirement": {
        "title": "Redact payment data before logging",
        "given": "a request or response containing card or account details",
        "when": "the gateway logs the body",
        "then": "primary account numbers, verification codes and bank account identifiers are masked or dropped, and the gateway fails closed (logs metadata only) if redaction cannot be applied"
      }
    },
    {
      "stride": "Spoofing",
      "title": "Session tokens captured in logged bodies and responses allow account impersonation",
      "scenario": "Login responses and authenticated request bodies carry session tokens, refresh tokens and API keys. Because full bodies and responses are logged, an attacker with log search access replays a still-valid token and acts as that user or service without ever knowing a password, defeating authentication and MFA.",
      "component": "Response body logging at API gateway",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        { "quote": "the API gateway logs full request and response bodies" }
      ],
      "asvs": ["V16.3.3"],
      "cwe": ["CWE-532", "CWE-539"],
      "plainLanguage": "Login tokens show up in the logs, so someone reading logs can reuse them and act as that user.",
      "requirement": {
        "title": "Strip tokens from logged payloads",
        "given": "a response or request containing a session, refresh or API token",
        "when": "the body is captured for debugging",
        "then": "token values are replaced with a non-reversible reference, and any token observed in a log triggers revocation"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Log system readers gain access to data they are not authorised to see in the application",
      "scenario": "The central log system is a shared debugging tool usually readable by developers, SRE and support staff, while payment and credential data in the application is restricted. Routing full bodies there lets a low-privilege employee or a compromised developer account read other customers' payment details and credentials through log search, bypassing the application's authorisation model.",
      "component": "Central log system access control",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        { "quote": "to the central log system for 1 year" }
      ],
      "asvs": [],
      "cwe": ["CWE-200", "CWE-863"],
      "plainLanguage": "Anyone who can search logs effectively gets to see payment and login data they could never see in the app itself.",
      "requirement": {
        "title": "Restrict and separate sensitive log streams",
        "given": "log records derived from authentication or payment traffic",
        "when": "a user queries the central log system",
        "then": "access is limited to a named, approved group with least privilege, separate from general application logs, and each access is attributable to an individual"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "One year of full-body retention makes any future log breach a mass data breach",
      "scenario": "Debugging integration issues needs hours or days of traffic, not a year. Keeping complete bodies for 12 months means a single later compromise of the log store, a misconfigured export, or a backup copy exposes a year of credentials, payment details and personal data at once instead of a small recent window.",
      "component": "Log retention policy",
      "likelihood": 3,
      "impact": 5,
      "evidence": [
        { "quote": "To debug integration issues, the API gateway logs full request and response bodies" },
        { "quote": "for 1 year" }
      ],
      "asvs": [],
      "cwe": ["CWE-212"],
      "plainLanguage": "Keeping full request contents for a year means one log leak exposes a whole year of sensitive data.",
      "requirement": {
        "title": "Minimise body-capture scope and retention",
        "given": "full body capture is enabled for an integration investigation",
        "when": "the capture is configured",
        "then": "it is limited to named routes, time-boxed to a short window with automatic expiry, and bodies are deleted well before the one-year metadata retention"
      }
    },
    {
      "stride": "DenialOfService",
      "title": "Attacker inflates log volume with large or repeated bodies to exhaust log storage",
      "scenario": "Since every body is logged in full, an unauthenticated or low-privilege caller sends many large request bodies to any gateway route. Log ingestion cost and storage spike, quotas are hit and genuine security-relevant log records are dropped or sampled away, blinding detection and degrading gateway throughput while the flood continues.",
      "component": "API gateway logging pipeline",
      "likelihood": 3,
      "impact": 3,
      "evidence": [
        { "quote": "the API gateway logs full request and response bodies, including login requests and payment details" }
      ],
      "asvs": [],
      "cwe": ["CWE-779", "CWE-770"],
      "plainLanguage": "Someone can send huge requests just to fill up the logs, pushing out the records you actually need.",
      "requirement": {
        "title": "Bound logged body size and volume",
        "given": "a request whose body exceeds a configured size or rate threshold",
        "when": "the gateway logs it",
        "then": "the body is truncated or omitted, the event is counted, and security-relevant log records are protected from being dropped by body-driven volume"
      }
    },
    {
      "stride": "Tampering",
      "title": "Attacker-controlled body content forges or corrupts log records",
      "scenario": "Request bodies are attacker-controlled text written into the log stream. By embedding newlines, control characters or fake JSON log fields, a caller injects entries that look like other users' actions or like system messages, hiding their own activity and misleading investigators and any downstream alerting that parses logs.",
      "component": "Log record construction at API gateway",
      "likelihood": 3,
      "impact": 3,
      "evidence": [
        { "quote": "the API gateway logs full request and response bodies" }
      ],
      "asvs": [],
      "cwe": ["CWE-117"],
      "plainLanguage": "Because raw request text goes straight into the logs, someone can fake log lines to cover their tracks.",
      "requirement": {
        "title": "Encode untrusted content in log records",
        "given": "a logged body containing newlines or control characters",
        "when": "the record is written to the central log system",
        "then": "the body is stored as an escaped single field so it cannot create or alter other log entries"
      }
    }
  ]
}
